import{z as B,x as d,o as r,c as A,q as o,j as s,D as a,d as E,s as n,S as i,b as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"承诺与 Merkle 树","description":"","frontmatter":{"title":"承诺与 Merkle 树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/commitment-merkle-tree.md","filePath":"cs/commitment-merkle-tree.md","lastUpdated":1791063341000}'),p={name:"cs/commitment-merkle-tree.md"};function m(C,e,c,h,k,D){const t=d("Mermaid");return r(),A("div",null,[e[2]||(e[2]=o('<h1 id="承诺与-merkle-树" tabindex="-1">承诺与 Merkle 树 <a class="header-anchor" href="#承诺与-merkle-树" aria-label="Permalink to &quot;承诺与 Merkle 树&quot;">​</a></h1><div class="epigraph"><p>承诺先把值藏进盒子：隐藏、绑定，稍后打开。Merkle 树把许多叶子收成一个根，证明某叶子在集合里只需一条路径，不必公开整棵树。</p><footer>—— 据 Pedersen 承诺；Merkle, Protocols for Public Key Cryptosystems, 1980；对照 RFC 6962 对 Merkle 的使用</footer></div><p>上一课<a href="/cs/zero-knowledge-intuition">零知识</a>常把承诺当内部消息。缺口是把<strong>承诺</strong>与<strong>集合摘要</strong>钉成工程对象。主干哈希已有；本课不重证碰撞，只讲绑定来自碰撞难、隐藏来自预像或盲随机。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ZK 的第一轮常是承诺。简单 \\(H(x\\|r)\\)：碰撞难则绑定，r 足够则隐藏。Pedersen 在离散对数假设下可加同态，本课点名。Merkle：叶哈希向上，包含证明是 \\(\\log n\\) 个兄弟。缺口是这两件零件，不是 CT 日志的政策（更后）。</p><p><span class="marginnote">术语翻译：承诺方案就像把答案写好装进信封再封口交给公证人——信封不透明，别人看不到答案（隐藏）；封口会留痕，你也改不了答案（绑定）；最后当众拆封，谁都能核对答案与当初一致（打开）。</span></p><h3 id="根换了就要重证" tabindex="-1">根换了就要重证 <a class="header-anchor" href="#根换了就要重证" aria-label="Permalink to &quot;根换了就要重证&quot;">​</a></h3><p>叶子一改根变。时间戳只钉某刻的根，不自动更新。</p><p><span class="marginnote">Merkle 1980。证书透明、Git、比特币都用变体；本课不进量化账本。隐藏在哈希承诺里对短 x 要加盐，否则可穷举。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写承诺的两条游戏。画一层 Merkle 路径。指出证明泄漏路径上的兄弟哈希，集合结构部分可见——需要时用更强的零知识集合。</p><p><span class="marginnote">数字实例：一百万个叶子时，一条包含证明只需 \\(\\log_2 10^6 \\approx 20\\) 个兄弟哈希，约 640 字节；若把整棵树下载下来核对，要传约 32 MB 的哈希。这就是「一条路径代替整棵树」的省法，也是证书透明日志可行的原因。</span></p>',13)),(r(),s(i,null,{default:a(()=>[n(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%80%BC%20x%22%5D%20--%3E%20COM%5B%22%E6%89%BF%E8%AF%BA%20Com(x%2Cr)%22%5D%0A%20%20COM%20--%3E%20OPEN%5B%22%E6%89%93%E5%BC%80%E5%87%BA%E7%A4%BA%20x%2Cr%22%5D%0A%20%20LEAVES%5B%22%E5%8F%B6%E5%AD%90%E5%93%88%E5%B8%8C%22%5D%20--%3E%20ROOT%5B%22Merkle%20%E6%A0%B9%22%5D%0A%20%20PATH%5B%22%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20INC%5B%22%E5%8C%85%E5%90%AB%E8%AF%81%E6%98%8E%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=l("h2",{id:"机制",tabindex:"-1"},[E("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=l("p",null,"绑定服务完整性：不能换叶子还声称同一根。隐藏服务保密：未打开前 x 不泄漏（在假设下）。二者与 AEAD 不同：承诺通常不传输「可解密的密文」，只传输可稍后打开的绑定。",-1)),(r(),s(i,null,{default:a(()=>[n(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20LEAF%5B%22%E7%9B%AE%E6%A0%87%E5%8F%B6%E5%AD%90%20L%22%5D%20--%3E%20H0%5B%22%E5%93%88%E5%B8%8C%20L%20%E5%BE%97%20h0%22%5D%0A%20%20SIB0%5B%22%E8%B7%AF%E5%BE%84%E4%B8%8A%E5%85%84%E5%BC%9F%E5%93%88%E5%B8%8C%200%22%5D%20--%3E%20H1%5B%22%E6%8B%BC%E5%93%88%E5%B8%8C%E5%BE%97%20h1%22%5D%0A%20%20H1%20--%3E%20SIB1%5B%22%E8%B7%AF%E5%BE%84%E4%B8%8A%E5%85%84%E5%BC%9F%E5%93%88%E5%B8%8C%201%22%5D%0A%20%20SIB1%20--%3E%20H2%5B%22%E5%86%8D%E6%8B%BC%E5%93%88%E5%B8%8C%2C%20%E9%80%90%E5%B1%82%E5%90%91%E4%B8%8A%22%5D%0A%20%20H2%20--%3E%20CMP%7B%22%E7%BB%93%E6%9E%9C%E7%AD%89%E4%BA%8E%E5%85%AC%E5%BC%80%E7%9A%84%E6%A0%B9%E5%90%97%22%7D%0A%20%20CMP%20--%3E%7C%22%E7%9B%B8%E7%AD%89%22%7C%20OK%5B%22L%20%E7%A1%AE%E5%AE%9E%E5%9C%A8%E9%9B%86%E5%90%88%E9%87%8C%22%5D%0A%20%20CMP%20--%3E%7C%22%E4%B8%8D%E7%AD%89%22%7C%20NO%5B%22%E8%AF%81%E6%98%8E%E5%A4%B1%E8%B4%A5%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[E(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=o('<p><span class="marginnote">常见误区：以为「隐藏」是自动的。直接对短消息哈希（比如「是/否」「同意/拒绝」）毫无保密性——攻击者可以把所有候选各哈希一遍对答案（字典穷举）。所以短值的哈希承诺必须混入足够长的随机数 \\(r\\)，让穷举无从对起。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把稀疏 Merkle 与 Verkle 写全。秘密共享下一课：把一个秘密拆给多人，与「承诺一个值」正交。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ZK 对话常吃承诺；本课钉隐藏与绑定。</li><li>Merkle 用哈希树做集合包含证明。</li><li>短消息承诺必须加盐，否则穷举破隐藏。</li><li>下一课 Shamir 秘密共享。</li><li>出处：Merkle, 1980；Pedersen；对照 Katz and Lindell 的承诺定义。</li></ul>',5))])}const f=B(p,[["render",m]]);export{_ as __pageData,f as default};
